// The TSIG keys (/dns/keys, scope `dns.keys`, administrators): name, algorithm, when created.
// A key is generated by the server or imported with a secret the person has; either way the
// secret is shown this once, in the pattern of the token and secrets areas (copy, confirm it is
// stored, close), and never again: the vault keeps it (purpose `tsig`). Delete asks first.
import { createSignal, For, Match, Show, Switch } from "solid-js";
import { createLiveQuery, latest } from "../api/live";
import { ConfirmDialog, Dialog } from "../components/Dialog";
import { Icon } from "../components/Icon";
import { ErrorNotice } from "../components/Notice";
import { PageHead } from "../components/PageHead";
import { toast } from "../components/toast";
import { DataGrid } from "../grid/DataGrid";
import { TimeAgo } from "../grid/cells";
import type { Column, RowAction } from "../grid/types";
import { t } from "../i18n";
import { copyValue } from "../secrets/clipboard";
import { createKey, deleteKey, listKeys, TSIG_ALGORITHMS, type DnsKey, type KeyCreated, type TsigAlgorithm } from "./api";
import { DnsNav } from "./DnsNav";
import { canonical, validName } from "./model";
import { describedBy, DnsProblem, Field, fieldErrors, unavailable } from "./Parts";
import "./dns.css";

function KeyDialog(props: { onClose: () => void; onCreated: () => void }) {
  let nameInput!: HTMLInputElement;
  const [mode, setMode] = createSignal<"generate" | "import">("generate");
  const [name, setName] = createSignal("");
  const [algorithm, setAlgorithm] = createSignal<TsigAlgorithm>("hmac-sha256");
  const [secret, setSecret] = createSignal("");
  const [description, setDescription] = createSignal("");
  const [errors, setErrors] = createSignal<Record<string, string>>({});
  const [error, setError] = createSignal<unknown>();
  const [busy, setBusy] = createSignal(false);
  const [created, setCreated] = createSignal<KeyCreated | null>(null);
  const [stored, setStored] = createSignal(false);

  const submit = async (event: Event) => {
    event.preventDefault();
    if (busy()) return;
    const e: Record<string, string> = {};
    if (!validName(canonical(name())) || canonical(name()) === ".") e.name = t("dns.check.name");
    if (mode() === "import" && !/^[A-Za-z0-9+/]{16,}={0,2}$/.test(secret().trim())) e.secret = t("dns.key.secret_invalid");
    setErrors(e);
    if (Object.keys(e).length > 0) return;
    setBusy(true);
    setError(undefined);
    try {
      const answer = await createKey({
        name: canonical(name()),
        algorithm: algorithm(),
        description: description().trim() || null,
        secret: mode() === "import" ? secret().trim() : null,
      });
      setSecret("");
      setCreated(answer);
      props.onCreated();
    } catch (err) {
      const fields = fieldErrors(err);
      if (Object.keys(fields).length > 0) setErrors(fields);
      else setError(err);
    } finally {
      setBusy(false);
    }
  };

  const closeWhenStored = () => {
    if (!created() || stored()) props.onClose();
  };

  const copy = async (value: string) => {
    const outcome = await copyValue(value);
    toast({ kind: outcome === "copied" ? "ok" : "bad", title: outcome === "copied" ? t("dns.key.copied") : t("dns.key.copy_blocked") });
  };

  return (
    <Switch>
      <Match when={created()}>
        {(answer) => (
          <Dialog label={t("dns.key.created_title")} onClose={closeWhenStored} class="dialog wide dns-dialog" testid="dialog-key-created">
            <h2 class="dialog-title">{t("dns.key.created_title")}</h2>
            <div class="dialog-body">
              <p>{t("dns.key.created_body", { name: answer().key.name })}</p>
              <dl class="kv">
                <dt>{t("dns.key.col.name")}</dt>
                <dd class="mono">{answer().key.name}</dd>
                <dt>{t("dns.key.col.algorithm")}</dt>
                <dd class="mono">{answer().key.algorithm}</dd>
              </dl>
              <div class="form-row">
                <code class="secret" data-testid="key-secret">
                  {answer().secret}
                </code>
                <button type="button" class="btn sm" data-testid="key-copy" onClick={() => void copy(answer().secret)}>
                  <Icon name="copy" size="sm" />
                  {t("common.action.copy")}
                </button>
              </div>
              <label class="ackrow">
                <input type="checkbox" class="cb" data-testid="key-stored" checked={stored()} onChange={(e) => setStored(e.currentTarget.checked)} />
                {t("dns.key.stored")}
              </label>
            </div>
            <div class="dialog-actions">
              <button type="button" class="btn primary" data-testid="key-done" disabled={!stored()} onClick={closeWhenStored}>
                {t("common.action.close")}
              </button>
            </div>
          </Dialog>
        )}
      </Match>
      <Match when={true}>
        <Dialog label={t("dns.key.create_title")} onClose={props.onClose} class="dialog wide dns-dialog" testid="dialog-key-form" initialFocus={() => nameInput}>
          <h2 class="dialog-title">{t("dns.key.create_title")}</h2>
          <form class="dialog-body dns-form" onSubmit={(e) => void submit(e)} novalidate>
            <fieldset class="dns-modes">
              <legend>{t("dns.key.mode")}</legend>
              <For each={["generate", "import"] as const}>
                {(m) => (
                  <label class="ackrow">
                    <input type="radio" name="dns-key-mode" checked={mode() === m} data-testid={`field-mode-${m}`} onChange={() => setMode(m)} />
                    {t(`dns.key.mode_${m}`)}
                  </label>
                )}
              </For>
            </fieldset>
            <Field id="name" label={t("dns.key.col.name")} error={errors().name} help={t("dns.key.name_help")}>
              <input
                ref={nameInput}
                id="dns-f-name"
                class="input mono"
                value={name()}
                spellcheck={false}
                autocomplete="off"
                aria-invalid={errors().name ? "true" : undefined}
                aria-describedby={describedBy("name", errors().name, "help")}
                data-testid="field-name"
                onInput={(e) => setName(e.currentTarget.value)}
              />
            </Field>
            <Field id="algorithm" label={t("dns.key.col.algorithm")}>
              <select id="dns-f-algorithm" class="select" value={algorithm()} data-testid="field-algorithm" onChange={(e) => setAlgorithm(e.currentTarget.value as TsigAlgorithm)}>
                <For each={TSIG_ALGORITHMS}>{(a) => <option value={a}>{a}</option>}</For>
              </select>
            </Field>
            <Show when={mode() === "import"}>
              <Field id="secret" label={t("dns.key.secret")} error={errors().secret} help={t("dns.key.secret_help")}>
                <input
                  id="dns-f-secret"
                  class="input mono"
                  type="password"
                  autocomplete="off"
                  value={secret()}
                  aria-invalid={errors().secret ? "true" : undefined}
                  aria-describedby={describedBy("secret", errors().secret, "help")}
                  data-testid="field-secret"
                  onInput={(e) => setSecret(e.currentTarget.value)}
                />
              </Field>
            </Show>
            <Field id="description" label={t("dns.zone.field.description")}>
              <input id="dns-f-description" class="input" value={description()} data-testid="field-description" onInput={(e) => setDescription(e.currentTarget.value)} />
            </Field>
            <ErrorNotice error={error()} />
            <div class="dialog-actions">
              <button type="button" class="btn ghost" data-testid="form-cancel" onClick={() => props.onClose()}>
                {t("common.action.cancel")}
              </button>
              <button type="submit" class="btn primary" data-testid="form-submit" disabled={busy()}>
                {mode() === "generate" ? t("dns.key.generate") : t("dns.key.import")}
              </button>
            </div>
          </form>
        </Dialog>
      </Match>
    </Switch>
  );
}

export default function KeysPage() {
  const [creating, setCreating] = createSignal(false);
  const [deleting, setDeleting] = createSignal<DnsKey | null>(null);
  const [busy, setBusy] = createSignal(false);
  const [deleteError, setDeleteError] = createSignal<unknown>();
  const query = createLiveQuery({
    topics: ["dns"],
    fetch: async (signal) => {
      const page = await listKeys(signal);
      return { value: page.items, revision: page.revision };
    },
  });
  const blocked = () => unavailable(query.value.error);

  const columns: Column<DnsKey>[] = [
    { id: "name", header: () => t("dns.key.col.name"), fixed: true, text: (k) => k.name, render: (k) => <span class="mono">{k.name}</span> },
    { id: "algorithm", header: () => t("dns.key.col.algorithm"), width: 160, text: (k) => k.algorithm, render: (k) => <span class="mono">{k.algorithm}</span> },
    { id: "created", header: () => t("dns.key.col.created"), width: 140, render: (k) => <TimeAgo at={k.created.at} /> },
    { id: "description", header: () => t("dns.col.description"), render: (k) => <span class="muted">{k.description ?? ""}</span> },
  ];
  const actions: RowAction<DnsKey>[] = [{ id: "delete", label: () => t("dns.do.delete"), danger: true, run: (k) => setDeleting(k) }];

  const confirmDelete = async (key: DnsKey) => {
    setBusy(true);
    setDeleteError(undefined);
    try {
      await deleteKey(key.name);
      toast({ kind: "ok", title: t("dns.key.deleted", { name: key.name }) });
      setDeleting(null);
      query.refetch();
    } catch (err) {
      setDeleteError(err);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div class="page dns-page list-page" data-testid="page-dns-keys">
      <DnsNav />
      <PageHead
        title={t("dns.keys.title")}
        sub={t("dns.keys.sub")}
        actions={
          <Show when={!blocked()}>
            <button type="button" class="btn primary" data-testid="dns-key-create" onClick={() => setCreating(true)}>
              <Icon name="key" />
              {t("dns.key.create_action")}
            </button>
          </Show>
        }
      />
      <Show when={!blocked()} fallback={<div class="page-body"><DnsProblem error={query.value.error} /></div>}>
        <div class="dns-list-body">
          <DataGrid
            id="dns-keys"
            label={t("dns.keys.title")}
            noSelection
            columns={columns}
            rows={latest(query) ?? []}
            rowId={(k) => k.id}
            rowKey={(k) => k.name}
            rowLabel={(k) => k.name}
            loading={query.value.loading}
            initial={latest(query) === undefined && !query.value.error}
            error={query.value.error}
            onRetry={query.refetch}
            rowActions={actions}
            empty={
              <div class="empty" data-testid="dns-keys-empty">
                <h3>{t("dns.keys.empty")}</h3>
              </div>
            }
          />
        </div>
      </Show>
      <Show when={creating()}>
        <KeyDialog onClose={() => setCreating(false)} onCreated={() => query.refetch()} />
      </Show>
      <Show when={deleting()} keyed>
        {(key) => (
          <ConfirmDialog
            title={t("dns.key.delete_title", { name: key.name })}
            testid="dialog-key-delete"
            danger
            busy={busy()}
            confirmLabel={t("dns.key.delete_confirm")}
            cancelLabel={t("common.action.cancel")}
            onClose={() => setDeleting(null)}
            onConfirm={() => void confirmDelete(key)}
            body={
              <>
                <p>{t("dns.key.delete_body")}</p>
                <ErrorNotice error={deleteError()} />
              </>
            }
          />
        )}
      </Show>
    </div>
  );
}
